def longest_winning_stretch(pnl):
    score = 0
    first = {}
    best = 0
    for day, x in enumerate(pnl):
        score += 1 if x > 0 else -1
        if score > 0:
            best = day + 1
        elif score - 1 in first:
            best = max(best, day - first[score - 1])
        if score not in first:
            first[score] = day
    return best
